INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch10$PT127-S1-Q10$batch10$, 127, 1, 10, $batch10$Main Conclusion$batch10$, $batch10$Prediction, the hallmark of the natural sciences, appears to have been made possible by reducing phenomena to mathematical expressions. Some social scientists also want the power to predict accurately and assume they ought to perform the same reduction. But this would be a mistake; it would neglect data that are not easily mathematized and thereby would only distort the social phenomena.$batch10$, $batch10$Which one of the following most accurately expresses the main conclusion of the argument?$batch10$, $batch10$D$batch10$, true, $batch10$Batch 10; question text from local bank.$batch10$ FROM lr_sections s WHERE s.preptest=127 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT127-S1-Q10$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$A$batch10$, $batch10$The social sciences do not have as much predictive power as the natural sciences.$batch10$, $batch10$Not Stated$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT127-S1-Q10$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$A$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$B$batch10$, $batch10$Mathematics plays a more important role in the natural sciences than it does in the social sciences.$batch10$, $batch10$Out of Scope$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT127-S1-Q10$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$B$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$C$batch10$, $batch10$There is a need in the social sciences to improve the ability to predict.$batch10$, $batch10$Opposing Point$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT127-S1-Q10$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$C$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$D$batch10$, $batch10$Phenomena in the social sciences should not be reduced to mathematical formulas.$batch10$, $batch10$Correct$batch10$, true FROM lr_questions q WHERE q.qid=$batch10$PT127-S1-Q10$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$D$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$E$batch10$, $batch10$Prediction is responsible for the success of the natural sciences.$batch10$, $batch10$Too Strong, Background$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT127-S1-Q10$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$E$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT127-S1-Q10$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Opposing Point$batch10$, $batch10$Some social scientists want predictive power and think they ought to reduce phenomena to math, as the natural sciences have.$batch10$), (1, $batch10$Conclusion$batch10$, $batch10$This would be a mistake.$batch10$), (2, $batch10$Evidence$batch10$, $batch10$Reducing social phenomena to math would neglect data that can't easily be put in mathematical terms, so it would distort the phenomena.$batch10$), (3, $batch10$Evaluate$batch10$, $batch10$"But this would be a mistake" is the pivot. Swap "this" for what it refers to: social scientists reducing social phenomena to mathematical expressions. The rest is the reason it's a mistake.$batch10$), (4, $batch10$Goal$batch10$, $batch10$Social scientists should not reduce social phenomena to mathematical formulas.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT127-S1-Q10$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$The argument doesn't compare how much predictive power each science has.$batch10$), ($batch10$B$batch10$, $batch10$The argument never ranks math's importance in the two fields.$batch10$), ($batch10$C$batch10$, $batch10$This is what the social scientists want. The author doesn't argue for it.$batch10$), ($batch10$D$batch10$, $batch10$With "this" filled in, the conclusion says reducing social phenomena to mathematical expressions would be a mistake. That's what D says.$batch10$), ($batch10$E$batch10$, $batch10$The first sentence says prediction is the hallmark of the natural sciences, not that it explains their success. And it's background, not the conclusion.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT127-S1-Q10$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
